    for f in fs:
        if f.endswith('.lean'):
            allf.add(os.path.join(d,f)[:-5].replace('/','.'))
unreach=sorted(allf-seen)
print('total modules:',len(allf),'reachable:',len(seen & allf),'UNREACHABLE:',len(unreach))
